<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useClock} from '../../composables/useClock.js'
import {useIrrigation} from '../../data/runtime.js'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import {stageNames,accountingNames,latest,stamp,shortStamp,sortRows,readingNumber,readingFacts} from './resourceUi.js'
const r=useIrrigation(),clock=useClock(),route=useRoute(),router=useRouter(),zoneId=ref(''),page=ref(1),sort=ref(null),water=ref(null),failure=ref('')
const e=computed(()=>r.state.entities),field=computed(()=>e.value.Field?.find(f=>f.fieldId===route.params.id)),zones=computed(()=>e.value.IrrigationZone?.filter(z=>z.fieldId===field.value?.fieldId)??[]),zone=computed(()=>zones.value.find(z=>z.zoneId===zoneId.value)??zones.value[0]),season=computed(()=>e.value.CropSeason?.find(s=>s.fieldId===field.value?.fieldId&&s.status==='ENABLED')),manager=computed(()=>e.value.User?.find(u=>u.userId===field.value?.managerId)?.name??'—')
const point=computed(()=>e.value.Point?.filter(p=>p.zoneId===zone.value?.zoneId&&p.kind==='SOIL_MOISTURE').sort((a,b)=>a.depthCm-b.depthCm)[0]),reading=computed(()=>latest(e.value.TelemetryReading??[],point.value?.pointId))
const moistureFacts=computed(()=>readingFacts(reading.value,point.value,e.value.Device?.find(d=>d.deviceId===point.value?.deviceId),clock.displayNow.value))
const runs=computed(()=>{const ids=new Set((e.value.RunStep??[]).filter(s=>zones.value.some(z=>z.zoneId===s.zoneId)).map(s=>s.runId));return sortRows((e.value.IrrigationRun??[]).filter(x=>ids.has(x.runId)&&['COMPLETED','STOPPED','FAILED'].includes(x.status)).sort((a,b)=>Date.parse(b.actualStartedAt??b.createdAt)-Date.parse(a.actualStartedAt??a.createdAt)),sort.value)})
watch(()=>[field.value?.fieldId,r.state.revision],async()=>{if(!field.value)return;try{water.value=await r.query('water',{fieldId:field.value.fieldId});failure.value=''}catch(e){failure.value=e.message}},{immediate:true})
const runWater=id=>water.value?.byRun?.find(x=>x.runId===id)?.volumeM3
const historicalWater=computed(()=>{if(!water.value)return null;const ids=new Set(runs.value.map(run=>run.runId));return (water.value.byRun??[]).filter(row=>ids.has(row.runId)).reduce((sum,row)=>sum+Number(row.volumeM3??0),0)})
const columns=[{key:'index',label:'序号',width:65},{key:'runId',label:'运行编号',sortable:true},{key:'actualStartedAt',label:'开始时间',sortable:true},{key:'actualEndedAt',label:'结束时间'},{key:'water',label:'实际水量m³'},{key:'status',label:'状态'}]
function monitor(){router.push({path:'/monitor',query:{zoneId:zone.value.zoneId,pointId:point.value.pointId,date:reading.value?.observedAt.slice(0,10)}})}
</script>
<template><div v-if="field" class="page-stack field-detail"><div class="back-row"><button class="btn" @click="router.push('/fields')">〈　返回</button><h2>{{field.code}}</h2></div><div class="detail-cards"><section class="panel"><h3 class="panel-title"><button v-if="r.can('FIELD_UPDATE',field)" class="btn-plain" title="编辑田块基本资料" @click="router.push('/fields/'+field.fieldId+'/edit')">田块基本信息</button><span v-else>田块基本信息</span></h3><dl class="data-pairs"><dt>田块名称</dt><dd>{{field.name}}</dd><dt>田块编号</dt><dd>{{field.code}}</dd><dt>面积（亩）</dt><dd>{{field.areaMu.toFixed(1)}}</dd><dt>土壤类型</dt><dd>{{field.soilType}}</dd><dt>地理位置</dt><dd>{{field.location.join('，')}}</dd><dt>负责人</dt><dd>{{manager}}</dd><dt>数据版本</dt><dd>{{field.version}}</dd></dl></section><section class="panel"><h3 class="panel-title">种植季信息</h3><dl v-if="season" class="data-pairs"><dt>作物</dt><dd>{{season.crop}}</dd><dt>品种</dt><dd>{{season.variety}}</dd><dt>播种日期</dt><dd>{{season.plantingDate}}</dd><dt>当前生育期</dt><dd>{{stageNames[season.stage]??season.stage}}</dd></dl><p v-else class="muted">暂无活动种植季</p></section><section class="panel"><h3 class="panel-title">相关分区信息</h3><select v-if="zones.length>1" v-model="zoneId"><option v-for="z in zones" :key="z.zoneId" :value="z.zoneId">{{z.name}}</option></select><dl v-if="zone" class="data-pairs"><dt>分区名称</dt><dd><button class="btn-link" @click="router.push({path:'/network',query:{zoneId:zone.zoneId}})">{{zone.name}}</button></dd><dt>分区编号</dt><dd>{{zone.zoneId}}</dd><dt>分区面积（亩）</dt><dd>{{zone.areaMu.toFixed(1)}}</dd><dt>计量方式</dt><dd>{{accountingNames[zone.accountingMethod]}}</dd></dl><p v-else class="muted">暂无关联分区</p></section></div><section class="panel moisture-profile"><h3 class="panel-title">根区墒情（单点剖面）</h3><div v-if="reading" class="profile-content"><button class="profile-depth btn-plain" @click="monitor"><svg width="340" height="138" viewBox="0 0 340 138"><text x="5" y="17" fill="#6b8490">深度（cm）</text><path d="M38 35h-5v96h5" fill="none" stroke="#304b54"/><text x="49" y="40">0</text><text x="49" y="88">{{point.depthCm}}</text><text x="49" y="136">{{Math.max(40,point.depthCm*2)}}</text><circle cx="33" cy="83" r="5" fill="#008853"/><text x="97" y="88">{{point.depthCm}}cm　{{readingNumber(reading.value)}}% VWC</text></svg></button><div class="profile-value"><div class="muted">{{point.depthCm}}cm土壤含水率</div><strong>{{readingNumber(reading.value)}}<small>% VWC</small></strong><p>采集时间：{{stamp(reading.observedAt)}}</p><span>数据状态： <StatusBadge :status="reading.quality"/></span><p v-if="moistureFacts" class="reading-facts warning-text" role="status">{{moistureFacts}}</p></div></div><p v-else class="empty-state">暂无关联土层读数</p></section><section class="panel history"><div class="history-title"><h3 class="panel-title">灌溉记录</h3><span class="muted">相关运行共{{runs.length}}条，15条/页，第{{page}}页；历史已结算水量{{historicalWater?.toFixed(1)??'—'}}m³</span><Pagination v-model="page" :total="runs.length" compact/></div><p v-if="failure" class="error-text">{{failure}}</p><DataTable :columns="columns" :rows="runs.slice((page-1)*15,page*15)" row-key="runId" compact v-model:sort="sort" @row-click="row=>router.push('/runs/'+row.runId)"><template #cell-index="{index}">{{(page-1)*15+index+1}}</template><template #cell-actualStartedAt="{value}">{{shortStamp(value)}}</template><template #cell-actualEndedAt="{value}">{{shortStamp(value)}}</template><template #cell-water="{row}">{{runWater(row.runId)?.toFixed(1)??'—'}}</template><template #cell-status="{value}"><StatusBadge :status="value"/></template></DataTable></section></div><div v-else class="panel empty-state">记录不存在 <button class="btn" @click="router.push('/fields')">返回田块列表</button></div></template>
<style scoped>.field-detail{gap:10px}.detail-cards{display:grid;grid-template-columns:36fr 30fr 33fr;gap:10px}.detail-cards .panel{min-height:234px;padding:10px 23px}.detail-cards .panel-title{margin-bottom:11px;font-size:18px}.detail-cards .data-pairs{gap:5px 25px}.detail-cards select{margin-bottom:8px;min-height:30px;padding:2px 8px}.moisture-profile{height:180px;padding-top:10px}.moisture-profile .panel-title{margin-bottom:0}.profile-content{display:flex;align-items:center;justify-content:center;gap:60px;margin-top:-10px}.profile-depth{width:370px;border-right:1px solid #d0dfe2}.profile-value{width:390px}.profile-value strong{font-size:42px;color:#079159}.profile-value small{font-size:27px}.profile-value p{margin:0 0 4px;color:#6a828a}.profile-value .reading-facts{font-size:12px;color:#ac670c}.history{padding-top:10px}.history-title{display:flex;align-items:center;justify-content:space-between}.history-title .panel-title{margin-bottom:10px}.history-title span{font-size:13px;margin-left:auto}.history-title :deep(.pagination){margin:0 0 6px 20px;min-height:30px}.history-title :deep(.pagination-summary){display:none}.history :deep(.data-table th){height:28px}.history :deep(.data-table td){height:22px;padding:1px 17px}.history :deep(.status-badge){font-size:12px;line-height:1.2;padding:1px 10px}@media(max-width:1000px){.detail-cards{grid-template-columns:1fr}.profile-content{gap:10px}.profile-depth{width:45%}}
</style>
